sys_script.script:
(function executeRule(current, previous) {
    if (current.u_expiry_date && current.u_mfg_date) {
        var gdtMfg = new GlideDateTime(current.u_mfg_date + ' 00:00:00');
        var gdtExpiry = new GlideDateTime(current.u_expiry_date + ' 00:00:00');
        if (gdtExpiry.getNumericValue() < gdtMfg.getNumericValue()) {
            gs.addErrorMessage('Expiry Date cannot be before Manufacturing Date.');
            current.setAbortAction(true);
            return;
        }
        var gdtNow = new GlideDateTime();
        var diffSec = (gdtExpiry.getNumericValue() - gdtNow.getNumericValue()) / 1000;
        var daysRem = Math.floor(diffSec / 86400);
        current.u_expiry_days_rem = daysRem;
        if (daysRem < 0) current.u_safety_status = 'expired';
        else if (daysRem <= 7) current.u_safety_status = 'near_expiry';
        else current.u_safety_status = 'safe';
    }
})(current, previous);
